const base = `
.demo{font-family:Inter,ui-sans-serif,system-ui,sans-serif;color:#f4f4f4;width:min(90vw,500px);box-sizing:border-box;font-size:12px;line-height:1.45;--lime:var(--accent,#ececec)}
.demo *{box-sizing:border-box}.demo button,.demo input{font:inherit}.demo button{cursor:pointer}.demo button:focus-visible,.demo input:focus-visible,.demo summary:focus-visible{outline:2px solid var(--lime);outline-offset:3px}.demo button{border:0}.demo .muted{color:#8e8e8e}.demo .lime{color:var(--lime)}.demo .pill{padding:5px 9px;border:1px solid #363636;border-radius:20px;font-size:9px;letter-spacing:.08em;text-transform:uppercase}.demo .primary{background:var(--lime);color:#1b1b1b;padding:10px 16px;border-radius:7px;font-weight:650}.demo .ghost{background:#222222;border:1px solid #393939;color:#e6e6e6;padding:9px 14px;border-radius:7px}.demo h1,.demo h2,.demo h3,.demo p{margin:0}.demo .tiny{font-size:9px}.demo svg{display:block}@media(prefers-reduced-motion:reduce){.demo *{animation:none!important;transition:none!important}}
`;
